        },
        {
          id: "q3",
          prompt: "Which languages are known for strong typing?",
          options: [
            "Java",
            "Go",
            "Bash",
            "C#",
          ],
        },
      ];

      function QuizHeader() {
        return `
          <header class="hero">
            <div class="eyebrow">Quiz</div>
            <h1>Computer Languages</h1>
            <p>Choose all answers that apply for each question. This quiz is built with a React-style component structure in a single HTML document.</p>
          </header>
        `;
      }

      function Question({ id, prompt, helpText, options }, index) {
        const fieldName = `${id}-choices`;
        return `
          <div class="form-field">
            <div class="question-header">
              <div>
                <h2 class="question-title">${index + 1}. ${prompt}</h2>
                ${helpText ? `<p class="question-help">${helpText}</p>` : ""}
              </div>
            </div>
            <div class="choice-list" role="group" aria-label="${prompt}">
              ${options
                .map(
                  (option, optionIndex) => `
                    <label class="choice">
                      <input type="checkbox" name="${fieldName}" value="${option}" />
                      <span>${String.fromCharCode(65 + optionIndex)}. ${option}</span>
                    </label>
                  `
                )
                .join("")}
            </div>
          </div>
        `;
      }

      function QuizApp() {
        return `
          <main class="page">
            <section class="quiz-shell" aria-labelledby="quiz-title">
              ${QuizHeader()}
              <form id="quiz-form">
                ${quizData.map(Question).join("")}
                <div class="actions">
                  <p class="status" id="status">Mark one or more answers for each question, then submit.</p>
                  <button class="submit-btn" type="submit">Submit Quiz</button>
                </div>
                <div id="result" class="result" hidden></div>
              </form>
            </section>
          </main>
        `;
      }

      document.getElementById("root").innerHTML = QuizApp();

      const form = document.getElementById("quiz-form");
      const status = document.getElementById("status");
      const result = document.getElementById("result");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const selections = quizData.map((question) => {
          const values = Array.from(
            form.querySelectorAll(`input[name="${question.id}-choices"]:checked`)
          ).map((input) => input.value);

          return `${question.prompt} — ${values.length ? values.join(", ") : "No selection"}`;
        });

        result.hidden = false;
        result.innerHTML = `
          <strong>Your selections:</strong>
          <ul>
            ${selections.map((line) => `<li>${line}</li>`).join("")}
          </ul>
        `;
        status.textContent = "Quiz submitted. Review your selections below.";
      });
